"""Build promotion studio and POS integration without altering other module bundles."""
from pathlib import Path
import re
root=Path(__file__).resolve().parents[1]
def read(p):return (root/p).read_text()
def write(p,s):(root/p).write_text(s)
def bundle(target,files,prefix='',suffix=''):
 write(target,'/* Generated by tools/build-promotions146.py. */\n'+prefix+'\n'+'\n;\n'.join('/* '+f+' */\n'+read(f) for f in files)+'\n;\n'+suffix)
core=['vendor/supabase-2.118.0.js','scripts/supabase-config.js','scripts/workspace-config123.js','scripts/restaurant-auth123.js','scripts/restaurant-backoffice.js','scripts/restaurant-permissions125.js','scripts/restaurant-modules125.js','scripts/restaurant-shell122.js','scripts/workspace-links123.js','scripts/restaurant-accounting124.js','scripts/restaurant-data144.js','scripts/restaurant-home139.js','scripts/word-of-hope183.js']
bundle('scripts/restaurant-core146.bundle.js',core,'window.restaurantBootLoading126=true;','window.restaurantBootLoading126=false;document.dispatchEvent(new Event("restaurant:boot126"));window.restaurantCoreReady146=true;')
bundle('scripts/restaurant-settings146.bundle.js',['scripts/public-content127.js','scripts/restaurant-settings125.js'])
bundle('scripts/restaurant-pos146.bundle.js',['scripts/pos-offline-v119.js','scripts/pos-performance125.js','scripts/pos-promotions146.js','scripts/pos-v118.js'])
boot=read('scripts/restaurant-bootstrap145.js').replace('145','146');write('scripts/restaurant-bootstrap146.js',boot);write('restaurant-sw146.js',read('restaurant-sw145.js').replace('145','146'))
for f in ['index.html','back-office/index.html']:
 s=read(f);s=re.sub(r'<script id="restaurantBoot\d+">.*?</script>','<script id="restaurantBoot146">'+boot+'</script>',s,flags=re.S);s=re.sub(r'<meta name="restaurant-release" content="[^"]+">','<meta name="restaurant-release" content="2026-10-27-promotions-vouchers-146">',s);write(f,s)
print('Built restaurant release 146.')
